#' Contraction hierarchies algorithm
#' @description Contract a graph by using contraction hierarchies algorithm.
#' @param Graph  An object generated by \link{makegraph} or \link{cpp_simplify} function.
#' @param silent Logical. If \code{TRUE}, progress is not displayed. Ignored when
#' \code{customizable = TRUE} (CCH preparation has no progress display).
#' @param customizable Logical. If \code{TRUE}, build a customizable contraction
#' hierarchy (CCH) instead of a classical one: only the graph topology is contracted, so
#' shortcut costs can be recomputed cheaply with \link{cpp_customize} whenever edge weights
#' change. See Details.
#' @param order Optional node order, only used when \code{customizable = TRUE}. Values must
#' be node references from \code{Graph$dict$ref}. If omitted, cppRouting computes a simple
#' local order. Large road networks usually benefit from a stronger nested-dissection order
#' prepared outside this function.
#' @return A contracted graph, or (when \code{customizable = TRUE}) a CCH topology object.
#' Run \link{cpp_customize} before distance queries on a CCH topology object, or pass it to
#' \link{assign_traffic} through the \code{cch} argument to avoid rebuilding the topology at
#' each model run.
#' @details Contraction hierarchies is a speed-up technique for finding shortest path in a graph.
#' It consist of two steps : preprocessing phase and query. \code{cpp_contract()} preprocess the input graph to later use special query algorithm implemented in \link{get_distance_pair}, \link{get_distance_matrix}, \link{get_aon} and \link{get_path_pair} functions.
#'
#' When \code{customizable = TRUE}, contraction is split into two phases instead: \itemize{
#'   \item \strong{Preparation} (this function): builds shortcuts from the road topology. This
#'   step is reusable as long as the set of edges does not change.
#'   \item \strong{Customization} (\link{cpp_customize}): updates shortcut costs from the
#'   current edge weights. This step is repeated when congestion changes travel times.
#' }
#' For traffic assignment, prepare once and call \code{assign_traffic(..., aon_method = "cch",
#' cch = cch)}. The CCH assignment path uses the elimination-tree query, which is the fast
#' query variant for repeated origins or repeated destinations.
#'
#' To see the benefits of using contraction hierarchies, see the package description : \url{https://github.com/vlarmet/cppRouting/blob/master/README.md}.
#' @seealso \link{cpp_simplify}
#' @examples
#' #Data describing edges of the graph
#' edges<-data.frame(from_vertex=c(0,0,1,1,2,2,3,4,4),
#'                   to_vertex=c(1,3,2,4,4,5,1,3,5),
#'                   cost=c(9,2,11,3,5,12,4,1,6))
#'
#' #Construct cppRouting graph
#' graph<-makegraph(edges,directed=TRUE)
#'
#' #Contract graph
#' contracted_graph<-cpp_contract(graph,silent=TRUE)
#'
#' #Build a customizable contraction hierarchy instead
#' cch <- cpp_contract(graph, customizable = TRUE)
#' metric <- cpp_customize(cch)
#' get_distance_pair(metric, from = 0, to = 3)


cpp_contract<-function(Graph,silent=FALSE,customizable=FALSE,order=NULL){
  if (!inherits(Graph, "cppRouting_graph")) stop("Input should be generated by makegraph() or cpp_simplify() function")

  if (customizable){
    if (is.null(order)){
      order_id <- integer(0)
    } else {
      order <- as.character(order)
      if (length(order) != Graph$nbnode) stop("order must contain one entry for each node")
      if (sum(order %in% Graph$dict$ref) < length(order)) stop("Some order nodes are not in the graph")
      if (any(duplicated(order))) stop("order contains duplicated nodes")
      order_id <- Graph$dict$id[match(order, Graph$dict$ref)]
    }

    cch <- cppcchprepare(Graph$data$from, Graph$data$to, Graph$nbnode, order_id)

    cch$nbnode <- Graph$nbnode
    cch$dict <- Graph$dict
    cch$original <- Graph[c("data", "attrib")]
    return(structure(cch, class = "cppRouting_cch"))
  }

  res <- cppcontract(Graph$data$from,Graph$data$to,Graph$data$dist,Graph$nbnode,!silent)



  structure(list(data=data.frame(from=res[[1]][[1]],
                                 to=res[[1]][[2]],
                                 dist=res[[1]][[3]]),
                 rank=res[[2]],
                 shortcuts=data.frame(shortf=res[[3]][[1]],
                                      shortt=res[[3]][[2]],
                                      shortc=res[[3]][[3]]),
                 nbnode=Graph$nbnode,
                 dict=Graph$dict,
                 original = Graph[c("data", "attrib")]),
            class = "cppRouting_contracted")
}
